import { Diagnostic, path } from '@servicenow/sdk-build-core'
import { Project } from '../../src'

describe('Record/Entity Interop Test Suite', () => {
    test('Records should be able to reference non-Record entities', async () => {
        const project = new Project({
            rootDir: path.resolve(__dirname, 'project'),
        })

        const index = project.findFile('index.now.ts')
        expect(index).toBeDefined()

        const diagnostics = await index.getDiagnostics()
        const errors = diagnostics.filter((d) => d.level === Diagnostic.Level.Error)
        expect(errors).toHaveLength(0)

        const records = await index.getRecords()
        expect(records.query()).toHaveLength(2)

        const appMenu = records.get('sys_app_application', '11111')
        expect(appMenu).toBeDefined()

        const appModule = records.get('sys_app_module', '22222')
        expect(appModule).toBeDefined()
        expect(appModule.get('application').toString().getValue()).toBe('11111') // Reference is established
    })
})
